window.POETRY_REGISTER("v5-strict-11-6-0-fd2deb736ad3.js",{"poems":[[19776,2],[22501,2],[22589,2],[52300,2],[52804,2],[53427,2],[97523,7],[183715,7],[230808,7],[233440,7],[247379,7],[290730,7],[293267,7],[332502,9],[368134,10],[417586,8],[540780,8],[544893,8],[584925,8],[584934,8],[635603,15],[680916,5],[692480,5],[711576,5]],"pairs":[["忽忽乎余未知生之为乐也","愿脱去而无因",0],["地上虮虱臣仝告愬帝天皇","臣心有铁一寸",1],["嗟自慙承夫子而不失予兮","传古道甚分明",2],["同治壬戌兵燹后石角斜泐","廑存八十四之",3],["如应麟以李适孙逖为盛唐","震亨改为初唐",4],["二句诗颂扬刺史善政多才","以崔作为近是",5],["朝之君臣兮犹燕巢于幕上","公对枰兮解颐",6],["云门扇子勃跳上三十三天","筑著帝释鼻孔",7],["有美一人兮居今而与古谋","气飘萧兮好修",8],["鄂渚豫章有虎狼之遗迹兮","曾不知其所重",9],["维千乘万骑之杂沓婐婉兮","犹彷徨其行声",10],["泰山之椒既风雨又艰险兮","乃登封以类告",10],["使吾冠冕佩玉于庙廊之上","吾不见其为泰",11],["使吾披裘带索于嵌岩之下","亦不见其为穷",11],["忽然遇维摩居士东指西指","又且如何对酬",12],["余方索居孑立而无与俦兮","聊逍遥乎林下",13],["自言五十五代孔子之孙孺","其母曰陶大家",14],["羡尔词源倒倾三峡楚天秋","清时肯卧林丘",15],["先生劝上帝以好生为大德","以清静为乐耽",16],["先生己未春曾为余叙拙稿","故结中致感云",17],["谅易词之不可以忞忞传兮","服楚言而恂恂",18],["何枘凿之终不可以相入兮","又竿瑟之异好",19],["方其阽身就死而无所恤兮","又孰念夫孤嫠",19],["残堞外一片荒鸡一半画笳","吹到孤眼人耳",20],["君不见南海之滨东山之阴","松苍苍兮石碧",21],["费惆怅似说星辰昨夜何许","雨叶风灯相乱",22],["愿寻干净之黄土兮抱夜月","而独上夫泉台",23]]});
